[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --bg-card: #141414;
      --bg-card-hover: #1a1a1a;
      --white: #FFFFFF;
      --gray-100: #f5f5f5;
      --gray-200: #e5e5e5;
      --gray-300: #d4d4d4;
      --gray-400: #a3a3a3;
      --gray-500: #737373;
      --gray-600: #525252;
      --gray-700: #404040;
      --gray-800: #262626;
      --gray-900: #171717;
      --accent: #3b82f6;
      --accent-hover: #60a5fa;
      --accent-warm: #f59e0b;
      --accent-warm-hover: #fbbf24;
    }

    html { font-size: 16px; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: var(--bg);
      color: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; color: inherit; }
    img { display: block; max-width: 100%; }

    /* Scrollbar */
    ::-webkit-scrollbar { height: 4px; width: 4px; }
    ::-webkit-scrollbar-track { background: transparent; }
    ::-webkit-scrollbar-thumb { background: var(--gray-700); border-radius: 4px; }

    /* ---- NAVIGATION ---- */
    .nav {
      position: fixed; top: 0; left: 0; right: 0; z-index: 100;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
      transition: background 0.3s;
    }
    .nav-inner {
      max-width: 1400px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 2rem; height: 64px;
    }
    .nav-logo {
      font-size: 1.25rem; font-weight: 800; letter-spacing: -0.03em;
      display: flex; align-items: center; gap: 0.5rem;
    }
    .nav-logo .dot { width: 8px; height: 8px; background: var(--accent); border-radius: 50%; }
    .nav-links { display: flex; align-items: center; gap: 1.75rem; }
    .nav-links a {
      font-size: 0.8125rem; font-weight: 500; letter-spacing: 0.02em;
      text-transform: uppercase; opacity: 0.7; transition: opacity 0.2s;
    }
    .nav-links a:hover { opacity: 1; }
    .nav-right { display: flex; align-items: center; gap: 1.25rem; }

    /* Language Selector */
    .lang-selector { position: relative; }
    .lang-btn {
      display: flex; align-items: center; gap: 0.4rem;
      font-size: 0.8125rem; font-weight: 500; opacity: 0.7;
      padding: 0.35rem 0; transition: opacity 0.2s;
    }
    .lang-btn:hover { opacity: 1; }
    .lang-btn svg { width: 14px; height: 14px; transition: transform 0.2s; }
    .lang-btn.open svg { transform: rotate(180deg); }
    .lang-dropdown {
      position: absolute; top: calc(100% + 8px); right: 0;
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.08);
      border-radius: 8px; min-width: 160px; padding: 0.25rem;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s ease;
      box-shadow: 0 16px 48px rgba(0,0,0,0.5);
    }
    .lang-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .lang-dropdown button {
      display: block; width: 100%; text-align: left;
      padding: 0.5rem 0.75rem; font-size: 0.8125rem; font-weight: 500;
      border-radius: 6px; transition: background 0.15s;
    }
    .lang-dropdown button:hover { background: rgba(255,255,255,0.06); }
    .lang-dropdown button.active { color: var(--accent); }

    /* Mobile menu */
    .mobile-menu-btn { display: none; flex-direction: column; gap: 5px; padding: 4px; }
    .mobile-menu-btn span { display: block; width: 22px; height: 2px; background: var(--white); border-radius: 2px; transition: all 0.3s; }
    .mobile-menu-btn.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .mobile-menu-btn.open span:nth-child(2) { opacity: 0; }
    .mobile-menu-btn.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    .mobile-nav {
      display: none; position: fixed; top: 64px; left: 0; right: 0; bottom: 0;
      background: var(--bg); z-index: 99; padding: 2rem;
      flex-direction: column; gap: 1.5rem;
    }
    .mobile-nav.open { display: flex; }
    .mobile-nav a {
      font-size: 1.25rem; font-weight: 600; padding: 0.5rem 0;
      border-bottom: 1px solid rgba(255,255,255,0.06);
    }

    @media (max-width: 900px) {
      .nav-links { display: none; }
      .mobile-menu-btn { display: flex; }
    }

    /* ---- HERO CAROUSEL ---- */
    .hero {
      position: relative; min-height: 100vh; overflow: hidden;
      display: flex; align-items: center; padding-top: 64px;
    }
    .hero-slides { position: relative; width: 100%; height: 100%; }
    .hero-slide {
      position: absolute; inset: 0;
      display: flex; align-items: center;
      opacity: 0; transition: opacity 0.8s ease;
      pointer-events: none;
    }
    .hero-slide.active { opacity: 1; pointer-events: auto; position: relative; }
    .hero-slide-inner {
      max-width: 1400px; margin: 0 auto; padding: 4rem 2rem;
      display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center;
      width: 100%;
    }
    .hero-text { max-width: 600px; }
    .hero-tag {
      display: inline-block; font-size: 0.6875rem; font-weight: 700;
      letter-spacing: 0.15em; text-transform: uppercase;
      color: var(--accent); margin-bottom: 1.25rem;
      padding: 0.35rem 0.75rem; border: 1px solid rgba(59,130,246,0.3);
      border-radius: 100px; background: rgba(59,130,246,0.08);
    }
    .hero-title {
      font-size: clamp(2.25rem, 5vw, 3.75rem); font-weight: 800;
      line-height: 1.05; letter-spacing: -0.03em; margin-bottom: 1.25rem;
    }
    .hero-desc {
      font-size: 1.0625rem; line-height: 1.7; color: var(--gray-300);
      margin-bottom: 2rem; max-width: 480px;
    }
    .hero-cta {
      display: inline-flex; align-items: center; gap: 0.5rem;
      font-size: 0.875rem; font-weight: 600;
      color: var(--accent); transition: color 0.2s;
    }
    .hero-cta:hover { color: var(--accent-hover); }
    .hero-cta svg { width: 18px; height: 18px; transition: transform 0.2s; }
    .hero-cta:hover svg { transform: translateX(4px); }

    .hero-visual {
      position: relative; border-radius: 16px; overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--bg-card) 0%, var(--gray-900) 100%);
    }
    .hero-visual-placeholder {
      width: 100%; height: 100%;
      display: flex; align-items: center; justify-content: center;
      font-size: 4rem; opacity: 0.15;
    }
    .hero-visual img { width: 100%; height: 100%; object-fit: cover; }

    /* Hero indicators */
    .hero-indicators {
      position: absolute; bottom: 2.5rem; left: 50%; transform: translateX(-50%);
      display: flex; gap: 0.5rem; z-index: 10;
    }
    .hero-dot {
      width: 32px; height: 3px; border-radius: 2px;
      background: rgba(255,255,255,0.25); transition: all 0.4s;
      cursor: pointer;
    }
    .hero-dot.active { background: var(--accent); width: 48px; }

    /* Hero nav arrows */
    .hero-arrows {
      position: absolute; bottom: 2.5rem; right: 2rem;
      display: flex; gap: 0.5rem; z-index: 10;
    }
    .hero-arrow {
      width: 44px; height: 44px; border-radius: 50%;
      border: 1px solid rgba(255,255,255,0.15);
      display: flex; align-items: center; justify-content: center;
      transition: all 0.2s;
    }
    .hero-arrow:hover { border-color: rgba(255,255,255,0.4); background: rgba(255,255,255,0.05); }
    .hero-arrow svg { width: 18px; height: 18px; }

    @media (max-width: 768px) {
      .hero-slide-inner { grid-template-columns: 1fr; gap: 2rem; padding: 3rem 1.5rem; }
      .hero-visual { aspect-ratio: 16/9; }
      .hero-arrows { display: none; }
    }

    /* ---- SECTION SHARED ---- */
    .section {
      max-width: 1400px; margin: 0 auto;
      padding: 6rem 2rem;
    }
    .section-label {
      font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.15em;
      text-transform: uppercase; color: var(--accent); margin-bottom: 1rem;
    }
    .section-title {
      font-size: clamp(2rem, 4vw, 3.25rem); font-weight: 800;
      line-height: 1.1; letter-spacing: -0.02em; margin-bottom: 1rem;
    }
    .section-subtitle {
      font-size: 1.0625rem; color: var(--gray-400); max-width: 600px; line-height: 1.7;
    }

    /* ---- TEAM / GLOBAL STUDIOS ---- */
    .team-section { background: var(--bg); }
    .region-tabs {
      display: flex; gap: 0.25rem; margin-bottom: 2.5rem;
      background: rgba(255,255,255,0.03); border-radius: 10px;
      padding: 0.25rem; width: fit-content;
      border: 1px solid rgba(255,255,255,0.06);
    }
    .region-tab {
      padding: 0.6rem 1.25rem; font-size: 0.8125rem; font-weight: 600;
      border-radius: 8px; transition: all 0.25s; color: var(--gray-400);
    }
    .region-tab:hover { color: var(--white); }
    .region-tab.active {
      background: var(--white); color: var(--bg);
    }

    .team-carousel-wrapper { position: relative; }
    .team-carousel {
      display: flex; gap: 1.5rem; overflow-x: auto; scroll-snap-type: x mandatory;
      scroll-behavior: smooth; padding-bottom: 1rem;
      -ms-overflow-style: none; scrollbar-width: none;
    }
    .team-carousel::-webkit-scrollbar { display: none; }

    .team-card {
      flex: 0 0 340px; scroll-snap-align: start;
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06);
      border-radius: 16px; overflow: hidden; transition: transform 0.3s, border-color 0.3s;
    }
    .team-card:hover { transform: translateY(-4px); border-color: rgba(255,255,255,0.12); }
    .team-card-photo {
      aspect-ratio: 1; background: linear-gradient(135deg, var(--gray-800), var(--gray-900));
      display: flex; align-items: center; justify-content: center;
      font-size: 3.5rem; opacity: 0.2; position: relative; overflow: hidden;
    }
    .team-card-photo::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(to top, var(--bg-card) 0%, transparent 50%);
    }
    .team-card-body { padding: 1.5rem; }
    .team-card-quote {
      font-size: 0.9375rem; line-height: 1.65; color: var(--gray-300);
      font-style: italic; margin-bottom: 1.25rem;
      display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
    }
    .team-card-name { font-weight: 700; font-size: 1rem; margin-bottom: 0.15rem; }
    .team-card-title { font-size: 0.8125rem; color: var(--gray-500); margin-bottom: 1rem; }
    .team-card-cta {
      display: inline-flex; align-items: center; gap: 0.4rem;
      font-size: 0.8125rem; font-weight: 600; color: var(--accent);
      transition: color 0.2s;
    }
    .team-card-cta:hover { color: var(--accent-hover); }
    .team-card-cta svg { width: 14px; height: 14px; }

    @media (max-width: 768px) {
      .team-card { flex: 0 0 300px; }
      .region-tabs { flex-wrap: wrap; }
    }

    /* ---- WORK SHOWCASE ---- */
    .work-section { position: relative; }
    .work-carousel {
      display: flex; gap: 1.5rem; overflow-x: auto; scroll-snap-type: x mandatory;
      scroll-behavior: smooth; padding-bottom: 1rem;
      -ms-overflow-style: none; scrollbar-width: none;
    }
    .work-carousel::-webkit-scrollbar { display: none; }

    .work-card {
      flex: 0 0 420px; scroll-snap-align: start;
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06);
      border-radius: 16px; overflow: hidden; transition: transform 0.3s, border-color 0.3s;
      cursor: pointer;
    }
    .work-card:hover { transform: translateY(-4px); border-color: rgba(255,255,255,0.12); }
    .work-card-thumb {
      aspect-ratio: 16/10; background: linear-gradient(135deg, var(--gray-800), var(--gray-900));
      display: flex; align-items: center; justify-content: center;
      font-size: 2.5rem; opacity: 0.15; overflow: hidden; position: relative;
    }
    .work-card-thumb::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(to top, var(--bg-card) 0%, transparent 60%);
    }
    .work-card-body { padding: 1.5rem; }
    .work-card-client {
      font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.12em;
      text-transform: uppercase; color: var(--accent); margin-bottom: 0.5rem;
    }
    .work-card-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 0.75rem; line-height: 1.3; }
    .work-card-quote {
      font-size: 0.875rem; line-height: 1.6; color: var(--gray-400);
      font-style: italic;
      display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
    }
    .work-card-quote cite { font-style: normal; color: var(--gray-500); display: block; margin-top: 0.35rem; font-size: 0.8125rem; }

    @media (max-width: 768px) {
      .work-card { flex: 0 0 320px; }
    }

    /* Carousel navigation arrows */
    .carousel-arrows { display: flex; gap: 0.5rem; margin-top: 1.5rem; }
    .carousel-arrow {
      width: 44px; height: 44px; border-radius: 50%;
      border: 1px solid rgba(255,255,255,0.12);
      display: flex; align-items: center; justify-content: center;
      transition: all 0.2s;
    }
    .carousel-arrow:hover { border-color: rgba(255,255,255,0.3); background: rgba(255,255,255,0.04); }
    .carousel-arrow svg { width: 18px; height: 18px; }

    /* ---- CTA BANNER ---- */
    .cta-banner {
      background: linear-gradient(135deg, rgba(59,130,246,0.08) 0%, rgba(59,130,246,0.02) 100%);
      border-top: 1px solid rgba(59,130,246,0.1);
      border-bottom: 1px solid rgba(59,130,246,0.1);
    }
    .cta-banner-inner {
      max-width: 1400px; margin: 0 auto; padding: 5rem 2rem;
      text-align: center;
    }
    .cta-banner-title {
      font-size: clamp(2rem, 4vw, 3.25rem); font-weight: 800;
      letter-spacing: -0.02em; margin-bottom: 1rem;
    }
    .cta-banner-text {
      font-size: 1.0625rem; color: var(--gray-400); max-width: 600px;
      margin: 0 auto 2rem; line-height: 1.7;
    }
    .cta-button {
      display: inline-flex; align-items: center; gap: 0.5rem;
      padding: 0.85rem 2rem; font-size: 0.9375rem; font-weight: 600;
      background: var(--white); color: var(--bg); border-radius: 100px;
      transition: all 0.25s;
    }
    .cta-button:hover { background: var(--gray-200); transform: translateY(-1px); }
    .cta-button svg { width: 18px; height: 18px; }

    /* ---- HOW WE WORK ---- */
    .how-section-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center;
    }
    .how-visual {
      aspect-ratio: 4/3; border-radius: 16px; overflow: hidden;
      background: linear-gradient(135deg, var(--bg-card) 0%, var(--gray-900) 100%);
      display: flex; align-items: center; justify-content: center;
      position: relative;
    }
    .how-visual::before {
      content: ''; position: absolute; inset: 0;
      background: radial-gradient(circle at 30% 40%, rgba(59,130,246,0.1), transparent 60%);
    }
    .how-visual-placeholder { font-size: 5rem; opacity: 0.1; }
    .how-text .section-subtitle { margin-bottom: 2rem; }

    @media (max-width: 768px) {
      .how-section-inner { grid-template-columns: 1fr; gap: 2rem; }
    }

    /* ---- INSIGHTS ---- */
    .insights-grid {
      display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
      gap: 1.25rem; margin-top: 3rem;
    }
    .insight-card {
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06);
      border-radius: 14px; overflow: hidden; transition: transform 0.3s, border-color 0.3s;
    }
    .insight-card:hover { transform: translateY(-3px); border-color: rgba(255,255,255,0.12); }
    .insight-thumb {
      aspect-ratio: 16/9; background: linear-gradient(135deg, var(--gray-800), var(--gray-900));
      display: flex; align-items: center; justify-content: center;
      font-size: 2rem; opacity: 0.15; position: relative;
    }
    .insight-thumb-type {
      position: absolute; top: 0.75rem; left: 0.75rem;
      font-size: 0.625rem; font-weight: 700; letter-spacing: 0.1em;
      text-transform: uppercase; padding: 0.25rem 0.6rem;
      border-radius: 100px; background: rgba(255,255,255,0.1);
      backdrop-filter: blur(8px);
    }
    .insight-body { padding: 1.25rem; }
    .insight-title { font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 0.75rem; }
    .insight-cta {
      display: inline-flex; align-items: center; gap: 0.35rem;
      font-size: 0.8125rem; font-weight: 600; color: var(--accent);
      transition: color 0.2s;
    }
    .insight-cta:hover { color: var(--accent-hover); }
    .insight-cta svg { width: 14px; height: 14px; }

    /* ---- PRINCIPLES ---- */
    .principles-grid {
      display: grid; grid-template-columns: repeat(4, 1fr);
      gap: 1.5rem; margin-top: 3rem;
    }
    .principle-card {
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06);
      border-radius: 16px; padding: 2rem; transition: transform 0.3s, border-color 0.3s;
      position: relative; overflow: hidden;
    }
    .principle-card:hover { transform: translateY(-3px); border-color: rgba(255,255,255,0.12); }
    .principle-card::before {
      content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
      background: linear-gradient(90deg, var(--accent), transparent);
    }
    .principle-number {
      font-size: 3rem; font-weight: 900; color: rgba(255,255,255,0.04);
      line-height: 1; margin-bottom: 1rem;
    }
    .principle-title { font-size: 1.125rem; font-weight: 700; margin-bottom: 0.75rem; line-height: 1.3; }
    .principle-desc { font-size: 0.9375rem; color: var(--gray-400); line-height: 1.65; }

    @media (max-width: 900px) {
      .principles-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 500px) {
      .principles-grid { grid-template-columns: 1fr; }
    }

    /* ---- FOOTER ---- */
    .footer {
      border-top: 1px solid rgba(255,255,255,0.06);
      background: var(--bg);
    }
    .footer-inner {
      max-width: 1400px; margin: 0 auto; padding: 4rem 2rem;
    }
    .footer-ctas {
      display: grid; grid-template-columns: 1fr 1fr; gap: 2rem;
      margin-bottom: 4rem;
    }
    .footer-cta-block {
      padding: 2rem; border-radius: 14px;
      background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06);
    }
    .footer-cta-text { font-size: 1rem; color: var(--gray-400); line-height: 1.65; margin-bottom: 1.25rem; }
    .footer-cta-link {
      display: inline-flex; align-items: center; gap: 0.4rem;
      font-size: 0.9375rem; font-weight: 600; color: var(--accent);
      transition: color 0.2s;
    }
    .footer-cta-link:hover { color: var(--accent-hover); }
    .footer-cta-link svg { width: 16px; height: 16px; }

    .footer-bottom {
      display: flex; justify-content: space-between; align-items: center;
      flex-wrap: wrap; gap: 1.5rem;
    }
    .footer-links { display: flex; gap: 2rem; flex-wrap: wrap; }
    .footer-links a {
      font-size: 0.875rem; color: var(--gray-500); transition: color 0.2s;
    }
    .footer-links a:hover { color: var(--white); }
    .footer-legal {
      font-size: 0.75rem; color: var(--gray-600); line-height: 1.7;
    }
    .footer-legal a { color: var(--gray-500); transition: color 0.2s; }
    .footer-legal a:hover { color: var(--gray-300); }

    @media (max-width: 768px) {
      .footer-ctas { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
    }

    /* ---- COOKIE CONSENT ---- */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
      background: var(--bg-card); border-top: 1px solid rgba(255,255,255,0.08);
      padding: 1.25rem 2rem;
      transform: translateY(100%); transition: transform 0.4s ease;
      box-shadow: 0 -8px 40px rgba(0,0,0,0.4);
    }
    .cookie-banner.visible { transform: translateY(0); }
    .cookie-inner {
      max-width: 1400px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between; gap: 2rem;
      flex-wrap: wrap;
    }
    .cookie-text { font-size: 0.875rem; color: var(--gray-300); line-height: 1.6; flex: 1; min-width: 280px; }
    .cookie-text a { color: var(--accent); text-decoration: underline; }
    .cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }
    .cookie-btn {
      padding: 0.55rem 1.25rem; font-size: 0.8125rem; font-weight: 600;
      border-radius: 100px; transition: all 0.2s;
    }
    .cookie-btn-accept { background: var(--white); color: var(--bg); }
